use pstfree::{ltp::{Heap,read_tc},ndb::Pst};use std::collections::BTreeMap;
fn u16b(b:&[u8],o:usize)->u16{u16::from_le_bytes(b[o..o+2].try_into().unwrap())}fn u32b(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let mut p=Pst::open(&std::env::args().nth(1).unwrap()).unwrap();let ns=p.nodes();let mut counts=BTreeMap::new();for n in ns.iter().filter(|n|matches!(n.nid_type(),14|15|16)){let h=Heap::new(p.node_blocks(n.bid_data).unwrap()).unwrap();let i=h.item(h.user_root).unwrap();let tags:BTreeMap<_,_>=i[22..].chunks_exact(8).map(|c|((u32b(c,0)>>16) as u16,u32b(c,0) as u16)).collect();for r in read_tc(&mut p,n.bid_data,n.bid_sub).unwrap().rows{if let Some(m)=ns.iter().find(|m|m.nid==r.id){let mh=Heap::new(p.node_blocks(m.bid_data).unwrap()).unwrap();let bh=mh.item(mh.user_root).unwrap();assert_eq!(bh[3],0);for rec in mh.item(u32b(bh,4)).unwrap().chunks_exact(8){let id=u16b(rec,0);let typ=u16b(rec,2);if let Some(t)=tags.get(&id){if !r.props.contains_key(&id) && m.nid_type()==4 {println!("ABSENT_CELL table={:x} item={:x} id={:04x} pc={:04x}",n.nid,m.nid,id,typ);}
if typ!=*t&&r.props.contains_key(&id){*counts.entry(format!("{:04x}:pc={:04x}:tc={:04x}",id,typ,t)).or_insert(0)+=1;println!("TYPE table={:x} item={:x} id={:04x} pc={:04x} tc={:04x}",n.nid,r.id,id,typ,t);}}}}}}println!("COUNTS {:?}",counts);}
